TLM.f("Sancti/09-17",{"officium":"Impressionis Stigmatum S. Francisci","rule":["vide C5;","9 lectiones"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."},{"k":"ref","la":"Ps 141:2"},{"k":"text","la":"Voce mea ad Dóminum clamávi: voce mea ad Dóminum deprecátus sum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, qui, frigescénte mundo, ad inflammándum corda nostra tui amóris igne, in carne beatíssimi Francísci passiónis tuæ sacra Stígmata renovásti: concéde propítius; ut ejus méritis et précibus crucem júgiter ferámus, et dignos fructus pæniténtiæ faciámus:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 6:14-18"},{"k":"text","la":"Fratres: Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo. In Christo enim Jesu neque circumcísio áliquid valet neque præpútium, sed nova creatúra. Et quicúmque hanc régulam secúti fúerint, pax sin per illos et misericórdia, et super Israël Dei. De cetero nemo mihi moléstus sit: ego enim stígmata Dómini Jesu in córpore meo porto. Grátia Dómini nostri Jesu Christi cum spíritu vestro, fratres. Amen."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Francíscus pauper et húmilis cœlum dives ingréditur, hymnis cœléstibus honorátur. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:24-27"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Si quis vult post me veníre, ábneget semetípsum, et tollat crucem suam, et sequátur me. Qui enim volúerit ánimam suam salvam fácere, perdet eam: qui autem perdíderit ánimam suam propter me, invéniet eam. Quid enim prodest hómini, si mundum univérsum lucrétur, ánimæ vero suæ detriméntum patiátur? Aut quam dabit homo commutatiónem pro ánima sua? Fílius enim hóminis ventúrus est in glória Patris sui cum Angelis suis: et tunc reddet unicuíque secúndum ópera ejus."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicata sanctífica: et, intercedénte beáto Francísco, ab omni nos culpárum labe purífica."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, qui mira Crucis mystéria in beáto Francísco Confessóre tuo multifórmiter demonstrásti: da nobis, quǽsumus; devotiónis suæ semper exémpla sectári, et assídua ejúsdem Crucis meditatióne muníri."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3ee5d112e28aad0a":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse Kriste, koji si, kad se svijet ohladio, u tijelu blaženoga Franje obnovio svete rane svoje muke da rasplamtiš naša srca ognjem svoje ljubavi, daj milostivo, da po njegovim zaslugama i molitvama stalno nosimo križ i donesemo dostojne plodove pokore:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine Isuse Kriste, koji si, kad je svijet ohladnio, u tijelu svetoga Franje obnovm svoje svete rane da, raspališ naša -srca ognjem^svo- II ljubavi. , dopusti mUostivo,, da njegovim zagovorom i mo.li,tvama neprestano nosimo kriz i vrS™ . ^ dostojna djela pokore; koji živiš i kraljuješ..-.- Evanđelje iz mise »Blagosivajte«, str. 792, _ ,","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"479d04a4222edf78":{"t":"Posveti, Gospodine, darove tebi namijenjene i po zagovoru blaženoga Franje od svake nas ljage grijeha očisti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, Gospođine, darove Tebi namijenjene i odvjetovanjem blaženoga Franje od svakog nas grijeha očisti; po G. n.","knRef":"Kniewald 1942, str. 726–727 (snimka 364) (OCR)"},"8ab7054569497988":{"t":"<i>Pomolimo se</i>.\nBože, koji si divne tajne križa mnogostruko pokazao u blaženom Franji priznavaocu svome, daj nam, molimo, da uvijek slijedimo primjere njegove pobožnosti i da se zaštitimo neprestanim razmatranjem istog križa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si čudesne tajne križa mnogostruko očitovao na svetom Franji, priznavao- cu svomu, daj nam, molimo,' da uvi jek'j nasljedujemo primjet njegove b6goljUibnoiSti''i da se iašti^ ' timo iieprestanim razmaitranjem križa, po G. n'.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"}}});
